import { describe, expect, it } from 'vitest';
import { splitChatMessagePreview } from './split-chat-message-preview';

describe('chat message preview', () => {
  it('leaves short text whole and prefers paragraph boundaries', () => {
    expect(splitChatMessagePreview('Short note')).toEqual({
      preview: 'Short note',
      remainder: null
    });
    const longMessage = `${'A useful sentence. '.repeat(26)}\n\nMore detail follows.`;
    expect(splitChatMessagePreview(longMessage)).toEqual({
      preview: 'A useful sentence. '.repeat(26).trimEnd(),
      remainder: 'More detail follows.'
    });
  });

  it.each([' ', '\t', '\n', '\u3000'])('uses a %j boundary before cutting a word', (separator) => {
    expect(splitChatMessagePreview(`First${separator}continuation`, 12)).toEqual({
      preview: 'First',
      remainder: 'continuation'
    });
  });

  it.each(['🎉', '🇯🇵', '👩🏽‍💻', 'e\u0301'])('keeps %s intact at the preview boundary', (grapheme) => {
    const prefix = '字'.repeat(499);
    expect(splitChatMessagePreview(`${prefix}${grapheme}続き`)).toEqual({
      preview: prefix,
      remainder: `${grapheme}続き`
    });
  });

  it('keeps an initial grapheme whole when it exceeds the limit', () => {
    expect(splitChatMessagePreview('👩🏽‍💻続き', 1)).toEqual({
      preview: '👩🏽‍💻',
      remainder: '続き'
    });
  });

  it('does not split a surrogate pair when Intl.Segmenter is unavailable', () => {
    const segmenter = Intl.Segmenter;
    Reflect.set(Intl, 'Segmenter', undefined);
    try {
      const prefix = '字'.repeat(499);
      expect(splitChatMessagePreview(`${prefix}🎉続き`)).toEqual({
        preview: prefix,
        remainder: '🎉続き'
      });
      expect(splitChatMessagePreview('🎉続き', 1)).toEqual({
        preview: '🎉',
        remainder: '続き'
      });
    } finally {
      Reflect.set(Intl, 'Segmenter', segmenter);
    }
  });
});

export function splitChatMessagePreview(
  text: string,
  maxPreviewLength = 500
): { preview: string; remainder: string | null } {
  if (text.length <= maxPreviewLength) return { preview: text, remainder: null };

  const limit = Math.max(1, Math.floor(maxPreviewLength));
  const paragraphBreak = text.lastIndexOf('\n\n', limit);
  let splitAt = limit;
  if (paragraphBreak > limit / 2) {
    splitAt = paragraphBreak;
  } else {
    for (let index = limit; index > 0; index--) {
      if (/\s/u.test(text[index] ?? '')) {
        splitAt = index;
        break;
      }
    }
  }

  if (typeof Intl.Segmenter === 'function') {
    const segments = new Intl.Segmenter(undefined, {
      granularity: 'grapheme'
    }).segment(text);
    for (const { index, segment } of segments) {
      if (index + segment.length > splitAt) {
        splitAt = index || segment.length;
        break;
      }
    }
  } else if (/^[\uDC00-\uDFFF]$/u.test(text[splitAt] ?? '')) {
    splitAt = splitAt === 1 ? 2 : splitAt - 1;
  }

  return {
    preview: text.slice(0, splitAt).trimEnd(),
    remainder: text.slice(splitAt).trimStart() || null
  };
}

/**
 * Dismisses an open popup (menu, popover) when the user scrolls the surrounding
 * scroller with the wheel, touch or keyboard — never on programmatic scrolling.
 * Call during component initialisation.
 */
export function useChatPopupDismissal(
  active: () => boolean,
  getTrigger: () => HTMLElement | null | undefined,
  onDismiss: () => void
): void {
  $effect(() => {
    const trigger = getTrigger();
    if (!active() || !trigger) return;
    const ownerDocument = trigger.ownerDocument;
    const onScrollInput = (event: Event): void => {
      if (!(event.target instanceof Element)) return;
      if (event.target.closest('[role="menu"], [data-slot="popover-popup"]')) return;
      if (event instanceof KeyboardEvent) {
        if (
          event.defaultPrevented ||
          ![
            'ArrowUp',
            'ArrowDown',
            'ArrowLeft',
            'ArrowRight',
            'PageUp',
            'PageDown',
            'Home',
            'End',
            ' '
          ].includes(event.key) ||
          event.altKey ||
          event.ctrlKey ||
          event.metaKey ||
          event.target.closest(
            'input, textarea, select, button, a, [contenteditable], [role=menu], [role=listbox], [role=combobox], [role=slider], [role=tablist]'
          )
        )
          return;
      }
      const isScrollable = (element: Element): boolean => {
        const style = getComputedStyle(element);
        const page = element === ownerDocument.scrollingElement;
        return (
          (element.scrollHeight > element.clientHeight &&
            (page || /auto|scroll/.test(style.overflowY))) ||
          (element.scrollWidth > element.clientWidth &&
            (page || /auto|scroll/.test(style.overflowX)))
        );
      };
      // Dismiss on input in the scroller, never on automatic scrolling or menu navigation.
      for (let element: Element | null = event.target; element; element = element.parentElement) {
        if (!isScrollable(element)) continue;
        if (element.contains(trigger)) onDismiss();
        return;
      }
      // Modal menus intercept wheel/touch input with a backdrop over the scroller.
      const point =
        event instanceof WheelEvent
          ? event
          : event instanceof TouchEvent
            ? event.touches[0]
            : undefined;
      if (!point) return;
      for (let element = trigger.parentElement; element; element = element.parentElement) {
        if (!isScrollable(element)) continue;
        const bounds = element.getBoundingClientRect();
        if (
          point.clientX >= bounds.left &&
          point.clientX <= bounds.right &&
          point.clientY >= bounds.top &&
          point.clientY <= bounds.bottom
        ) {
          onDismiss();
          return;
        }
      }
    };
    const scrollInputs = ['wheel', 'touchmove', 'keydown'] as const;
    for (const type of scrollInputs)
      ownerDocument.addEventListener(type, onScrollInput, { passive: true });
    return () => {
      for (const type of scrollInputs) ownerDocument.removeEventListener(type, onScrollInput);
    };
  });
}

import { prefersReducedMotion } from 'svelte/motion';
export type ChatScrollOptions = {
  active?: boolean;
  paused?: boolean;
  itemCount: number;
  layoutKey?: string | number;
  onReachEnd?: () => void;
};

/**
 * Keeps a chat viewport pinned to the latest message and tracks whether the
 * reader scrolled away. Must be constructed during component initialisation.
 */
export class ChatScroll {
  #options: () => ChatScrollOptions;
  viewport = $state<HTMLElement | null>(null);
  showJump = $state(false);
  /** Whether the viewport is (close to) the bottom; read and written imperatively. */
  atBottom = true;

  constructor(options: () => ChatScrollOptions) {
    this.#options = options;

    // Follow content changes before scroll events can misinterpret the new height.
    $effect(() => {
      const { active = true, paused = false, itemCount, layoutKey } = this.#options();
      void itemCount;
      void layoutKey;
      const viewport = this.viewport;
      if (!active || paused || !viewport) return;
      if (this.atBottom) {
        viewport.scrollTop = viewport.scrollHeight;
        this.showJump = false;
      } else {
        this.showJump = viewport.scrollHeight - viewport.scrollTop - viewport.clientHeight > 64;
      }
    });

    $effect(() => {
      const { active = true, paused = false } = this.#options();
      const viewport = this.viewport;
      if (!active || paused || !viewport) return;
      let observer: ResizeObserver | undefined;
      const frame = requestAnimationFrame(() => {
        observer = new ResizeObserver(() => {
          if (this.atBottom) viewport.scrollTop = viewport.scrollHeight;
        });
        observer.observe(viewport);
        if (viewport.firstElementChild) observer.observe(viewport.firstElementChild);
      });
      return () => {
        cancelAnimationFrame(frame);
        observer?.disconnect();
      };
    });
  }

  updatePosition = (): void => {
    const viewport = this.viewport;
    this.atBottom = Boolean(
      viewport && viewport.scrollHeight - viewport.scrollTop - viewport.clientHeight < 64
    );
  };

  onScroll = (): void => {
    const { paused = false, onReachEnd } = this.#options();
    if (paused) return;
    this.updatePosition();
    this.showJump = !this.atBottom;
    if (this.atBottom) onReachEnd?.();
  };

  resetScroll = (atBottom = true): void => {
    this.atBottom = atBottom;
    this.showJump = !atBottom;
    requestAnimationFrame(() => {
      const viewport = this.viewport;
      if (viewport) viewport.scrollTop = atBottom ? viewport.scrollHeight : 0;
    });
  };

  scrollToLatest = (): void => {
    this.atBottom = true;
    this.viewport?.scrollTo({
      top: this.viewport.scrollHeight,
      behavior: prefersReducedMotion.current ? 'auto' : 'smooth'
    });
  };
}
